-- ============================================================
-- Integrate.sql
-- Integration: Fantasy Football DB (Premier League) + FIFA World Cup DB
-- ============================================================

-- ============================================================
-- STEP 1: Create new tables from the RL (FIFA World Cup) system
-- ============================================================

-- 1.1 person - supertype for international players and referees
CREATE TABLE public.person (
    id            CHARACTER VARYING(50) NOT NULL,
    familyname    TEXT,
    givenname     TEXT NOT NULL,
    wikipediapage TEXT,
    CONSTRAINT person_pkey PRIMARY KEY (id)
);

-- 1.2 intl_team - national football teams (distinct from real_team = club teams)
CREATE TABLE public.intl_team (
    teamcode          CHARACTER VARYING(50) NOT NULL,
    countryname       TEXT NOT NULL,
    confederationname TEXT NOT NULL,
    confederationcode CHARACTER VARYING(50) NOT NULL,
    wikipediapage     TEXT,
    CONSTRAINT intl_team_pkey PRIMARY KEY (teamcode)
);

-- 1.3 stadium - World Cup stadiums
CREATE TABLE public.stadium (
    stadiumid     CHARACTER VARYING(50) NOT NULL,
    city          TEXT NOT NULL,
    name          TEXT NOT NULL,
    capacity      INTEGER NOT NULL,
    wikipediapage TEXT,
    country       TEXT NOT NULL,
    CONSTRAINT stadium_pkey PRIMARY KEY (stadiumid)
);

-- 1.4 referee - match referees (person subtype)
CREATE TABLE public.referee (
    id                CHARACTER VARYING(50) NOT NULL,
    country           TEXT NOT NULL,
    confederationcode CHARACTER VARYING(50) NOT NULL,
    confederationname TEXT NOT NULL,
    CONSTRAINT referee_pkey   PRIMARY KEY (id),
    CONSTRAINT referee_person_fkey FOREIGN KEY (id) REFERENCES public.person(id)
);

-- 1.5 intl_player - World Cup players (person subtype, belongs to national team)
CREATE TABLE public.intl_player (
    id          CHARACTER VARYING(50) NOT NULL,
    dateofbirth DATE,
    teamcode    CHARACTER VARYING(50),
    CONSTRAINT intl_player_pkey      PRIMARY KEY (id),
    CONSTRAINT intl_player_pers_fkey FOREIGN KEY (id)       REFERENCES public.person(id),
    CONSTRAINT intl_player_team_fkey FOREIGN KEY (teamcode) REFERENCES public.intl_team(teamcode)
);

-- 1.6 intl_match - FIFA World Cup matches (distinct from match = Premier League matches)
CREATE TABLE public.intl_match (
    matchid       CHARACTER VARYING(50) NOT NULL,
    matchdate     DATE NOT NULL,
    stage         TEXT NOT NULL,
    tournament    TEXT NOT NULL,
    matchtime     TIME WITHOUT TIME ZONE,
    stadiumid     CHARACTER VARYING(50) NOT NULL,
    guestteamcode CHARACTER VARYING(50) NOT NULL,
    hometeamcode  CHARACTER VARYING(50) NOT NULL,
    refereeid     CHARACTER VARYING(50) NOT NULL,
    CONSTRAINT intl_match_pkey         PRIMARY KEY (matchid),
    CONSTRAINT intl_match_stadium_fkey FOREIGN KEY (stadiumid)     REFERENCES public.stadium(stadiumid),
    CONSTRAINT intl_match_guest_fkey   FOREIGN KEY (guestteamcode) REFERENCES public.intl_team(teamcode),
    CONSTRAINT intl_match_home_fkey    FOREIGN KEY (hometeamcode)  REFERENCES public.intl_team(teamcode),
    CONSTRAINT intl_match_ref_fkey     FOREIGN KEY (refereeid)     REFERENCES public.referee(id)
);

-- 1.7 match_event - goals, cards, etc. in World Cup matches
CREATE TABLE public.match_event (
    matcheventid CHARACTER VARYING(50) NOT NULL,
    minute       TEXT NOT NULL,
    eventtype    TEXT NOT NULL,
    matchid      CHARACTER VARYING(50) NOT NULL,
    id           CHARACTER VARYING(50) NOT NULL,
    CONSTRAINT match_event_pkey        PRIMARY KEY (matcheventid),
    CONSTRAINT match_event_match_fkey  FOREIGN KEY (matchid) REFERENCES public.intl_match(matchid),
    CONSTRAINT match_event_player_fkey FOREIGN KEY (id)      REFERENCES public.intl_player(id)
);

-- 1.8 intl_player_match_stats - position and shirt number in World Cup match
CREATE TABLE public.intl_player_match_stats (
    matchid     CHARACTER VARYING(50) NOT NULL,
    playerid    CHARACTER VARYING(50) NOT NULL,
    position    TEXT NOT NULL,
    shirtnumber INTEGER NOT NULL,
    CONSTRAINT intl_pms_pkey        PRIMARY KEY (matchid, playerid),
    CONSTRAINT intl_pms_match_fkey  FOREIGN KEY (matchid)  REFERENCES public.intl_match(matchid),
    CONSTRAINT intl_pms_player_fkey FOREIGN KEY (playerid) REFERENCES public.intl_player(id)
);

-- ============================================================
-- STEP 2: Modify existing tables to add integration links
-- ============================================================

-- Link Premier League club players to their international identity (person)
-- Allows queries like: "which PL players also appeared in World Cup data?"
ALTER TABLE public.player
    ADD COLUMN person_id CHARACTER VARYING(50),
    ADD CONSTRAINT player_person_id_fkey FOREIGN KEY (person_id) REFERENCES public.person(id);

